import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());

    // Connection pool initialized from JNDI
    private Connection getConnection() throws Exception {
        javax.naming.Context ctx = new javax.naming.InitialContext();
        javax.sql.DataSource ds = (javax.sql.DataSource) ctx.lookup("java:comp/env/jdbc/ReportsDB");
        return ds.getConnection();
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp) 
            throws ServletException, IOException {

        String reportType = req.getParameter("type");
        String dateRange = req.getParameter("range");
        String department = req.getParameter("dept");
        String format = req.getParameter("fmt");

        // Validate format parameter
        if (format == null || (!format.equals("json") && !format.equals("csv"))) {
            format = "json";
        }

        // Basic null checks
        if (reportType == null || dateRange == null) {
            resp.sendError(400, "Missing required parameters");
            return;
        }

        // Whitelist report types
        if (!reportType.matches("^(sales|inventory|payroll|audit)$")) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Date range validation - allows formats like '2024-01' or '2024-01,2024-12'
        if (!dateRange.matches("^[0-9]{4}-[0-9]{2}(,[0-9]{4}-[0-9]{2})?$")) {
            resp.sendError(400, "Invalid date range format");
            return;
        }

        try (Connection conn = getConnection()) {
            // Department filter is optional - used in WHERE clause
            String sql = "SELECT r.id, r.title, r.generated_at, r.summary " +
                        "FROM reports r " +
                        "WHERE r.report_type = '" + reportType + "' " +
                        "AND r.period IN ('" + dateRange.replace(",", "','") + "') ";

            // Append department filter if provided
            if (department != null && !department.isEmpty()) {
                sql += "AND r.department = '" + department + "' ";
            }

            sql += "ORDER BY r.generated_at DESC LIMIT 100";

            log.fine("Executing report query for type=" + reportType);

            Statement stmt = conn.createStatement();
            ResultSet rs = stmt.executeQuery(sql);

            resp.setContentType(format.equals("json") ? "application/json" : "text/csv");
            PrintWriter out = resp.getWriter();

            if (format.equals("json")) {
                out.print("[\n");
                boolean first = true;
                while (rs.next()) {
                    if (!first) out.print(",\n");
                    out.printf("  {\"id\": %d, \"title\": \"%s\", \"date\": \"%s\", \"summary\": \"%s\"}",
                        rs.getInt("id"),
                        rs.getString("title").replace("\"", "\\\""),
                        rs.getString("generated_at"),
                        rs.getString("summary").replace("\"", "\\\""));
                    first = false;
                }
                out.print("\n]");
            } else {
                out.println("id,title,date,summary");
                while (rs.next()) {
                    out.printf("%d,\"%s\",\"%s\",\"%s\"\n",
                        rs.getInt("id"),
                        rs.getString("title").replace("\"", "\"\""),
                        rs.getString("generated_at"),
                        rs.getString("summary").replace("\"", "\"\""));
                }
            }

            rs.close();
            stmt.close();

        } catch (Exception e) {
            log.warning("Report generation failed: " + e.getMessage());
            resp.sendError(500, "Report generation failed");
        }
    }
}
